<template>
	<div>
		<common-tooltip class="setting-label" tag-name="p">
			<template #tooltip
				>Manually insert your campaign or configure and display it automatically. Advanced output settings are
				still in effect.</template
			>
			<span>How should your inline campaign be displayed?</span>
		</common-tooltip>

		<common-selectable-group
			wrap-tag="p"
			group-name="settingAutomatic"
			:options="[
				{
					label: 'Manual',
					value: '0',
					help: 'Insert the campaign manually in your post or page.',
					checked: !isAuto,
				},
				{
					label: 'Automatic',
					value: '1',
					help: 'Configure and display your campaign automatically.',
					checked: isAuto,
				},
			]"
			@input="setValue"
		/>

		<div
			v-if="isAuto"
			class="omapi-radio-group omapi-radio-group__indent omapi-radio-group__with-inputs omapi-input"
		>
			<common-selectable-input
				value="words"
				name="settingAutoLocation"
				:checked="'words' === settingAutoLocation"
				@input="setCompooundValue($event, $refs.afterWords, 300)"
			>
				After
				<input
					ref="afterWords"
					v-model.number="settingAutoLocationWords"
					class="omapi-input omapi-input__inline"
					name="settingAutoLocationWords"
					type="number"
					min="1"
					width="4"
					style="flex-basis: 54px"
				/>
