			</common-selectable-input>
			<common-selectable-input
				value="paragraphs"
				name="settingAutoLocation"
				:checked="'paragraphs' === settingAutoLocation"
				@input="setCompooundValue($event, $refs.afterParagraphs, 3)"
			>
				After
				<input
					ref="afterParagraphs"
					v-model.number="settingAutoLocationParagraphs"
					class="omapi-input omapi-input__inline"
					name="settingAutoLocationParagraphs"
					type="number"
					min="1"
					width="4"
					style="flex-basis: 54px"
				/>
