			</common-selectable-input>
			<common-selectable-input
				label="Below Post"
				value="below_post"
				name="settingAutoLocation"
				:checked="'below_post' === settingAutoLocation || !settingAutoLocation"
				@input="setValue"
			/>
			<common-selectable-input
				label="Above Post"
				value="above_post"
				name="settingAutoLocation"
				:checked="'above_post' === settingAutoLocation"
				@input="setValue"
			/>
		</div>

