	</div>
</template>

<script lang="js">
import { campaign } from '@/campaigns/mixins/campaign';

export default {
	mixins: [campaign],
	props: {
		campaign: {
			type: Object,
			required: true,
		},
	},
	computed: {
		isAuto() {
			return '1' === this.settingAutomatic;
		},
	},
};
</script>
